#include "support/ws_reconnect_peer.h"
#include "support/ws_resume_peer.h"
typedef struct mcService {wrService Base;mrState TLS;xtlsresume* Credential;xatomic32 Configured,Issued,Resumed;} mcService;
static void mcConfigure(xnetworker* W,ptr Data)
{(void)W;mcService* S=Data;for(unsigned I=0;I<8;++I){S->Base.Connections[I].Peer.Base.NativeServer.Resume=mrLookup;S->Base.Connections[I].Peer.Base.NativeServer.ResumeContext=&S->TLS;}xrtAtomic32Store(&S->Configured,1,XMEMORY_RELEASE);}
static xmqttclientstatus mcFactory(xnetengine* E,uint64 A,const xmqttclientconfig* K,xmqttsession* Session,xmqttclientinbox* Inbox,const xmqttpacket* Q,ptr Data,xmqttclient** Out)
{
    mcService* S=Data;xmqttclientwsconnectconfig W;xmqttClientWsConnectConfigInit(&W);W.Host=XRT_STR_LITERAL("example.com");W.Target=XRT_STR_LITERAL("/mqtt?x=%00");W.WebSocket.Session=Session;W.WebSocket.Inbox=Inbox;xmqttclienttlsconfig T;xmqttClientTlsConfigInit(&T);T.Session.Context=S->Base.Context;T.Session.Verifier=S->Base.Verifier;T.Session.ServerName=T.Session.VerifyName=XRT_STR_LITERAL("example.com");T.Session.Resume=S->Credential;T.Session.ResumeOnly=S->Credential!=NULL;bool OK; if(S->Base.Route==0)OK=xmqttClientWssConnect(E,&S->Base.Address,A,K,&W,&T,Q,Out);else OK=xmqttClientWssConnectUri(E,S->Base.Resolver,(xstrview){S->Base.URI,strlen(S->Base.URI)},A,K,&W,&T,Q,Out);xrtAtomic32FetchAdd(&S->Base.Factories,1,XMEMORY_RELEASE);return OK?XMQTT_STATUS_OK:XMQTT_STATUS_INITIALIZATION;
}
static void mcIssueTask(xnetworker* W,ptr Data)
{(void)W;mcService* S=Data;unsigned Accepted=xrtAtomic32Load(&S->Base.Accepted,XMEMORY_ACQUIRE);if(!Accepted||Accepted>8){testRequire(false,"ticket issue requires an accepted native peer");return;}xwsstream* WS=xrtAtomicPtrLoad(&S->Base.Connections[Accepted-1].Peer.Base.Server,XMEMORY_ACQUIRE);xtlsstream* Native=xrtWsStreamTls(WS);xtlsresume* Next=NULL;testRequire(xrtTlsServerTicketNew(xrtTlsStreamSession(Native),&Next)==XTLS_OK&&xrtTlsStreamFlush(Native)==XTLS_OK,"actual automatic-generation ticket issue");xrtTlsResumeRelease(S->TLS.ServerTicket);S->TLS.ServerTicket=Next;xrtAtomic32Store(&S->Resumed,xrtTlsServerResumed(xrtTlsStreamSession(Native)),XMEMORY_RELEASE);xrtAtomic32FetchAdd(&S->Issued,1,XMEMORY_RELEASE);}
static void mcIssue(mcService* S)
{uint32 Before=xrtAtomic32Load(&S->Issued,XMEMORY_ACQUIRE);testRequire(xrtNetEnginePost(S->Base.Engine,0,mcIssueTask,S),"issue on automatic peer owner");mqttWsWait(&S->Issued,Before+1,"actual generation ticket output");}
static void mcCase(xmqttversion Version,unsigned Route,unsigned Cut)
{
    mcService S={0};wrStart(&S.Base,true,Version,Route,XNET_PORT_SELECT);xrtAtomic32Store(&S.Base.Cut,Cut,XMEMORY_RELEASE);testRequire(xrtNetEnginePost(S.Base.Engine,0,mcConfigure,&S),"configure automatic native PSK lookup");mqttWsWait(&S.Configured,1,"PSK server configured");xmqttreconnectconfig K;xmqttReconnectConfigInit(&K);K.Client.Version=Version;K.Factory=mcFactory;K.FactoryData=&S;K.InitialDelay=5;K.MaxDelay=20;K.JitterPermille=0;K.RecoveryTimeout=10000;xmqttpacket Q;xmqttPacketInit(XMQTT_PACKET_CONNECT,&Q);Q.Body.Connect.ClientId=XRT_STR_LITERAL("ws-managed");Q.Body.Connect.CleanStart=Version==XMQTT_VERSION_5;xmqttproperty Expiry={0};Expiry.Id=XMQTT_PROPERTY_SESSION_EXPIRY;Expiry.Type=XMQTT_PROPERTY_UINT32;Expiry.Value.Number=60;if(Version==XMQTT_VERSION_5)Q.Properties=(xmqttpropertylist){&Expiry,1};xmqttreconnect* R=NULL;testRequire(xmqttReconnectCreate(S.Base.Engine,S.Base.Pool,1,&K,&Q,&R),"existing automatic controller with WSS cache factory");xmqttclientlease L={0};wrOnline(R,1,&L);mcIssue(&S);testRequire(!mrCaptured(L.Client,1).Resumed&&xmqttClientTlsTakeResume(L.Client,&S.Credential),"first TLS generation supplies independent immutable credential");
    xmqttPacketInit(XMQTT_PACKET_PUBLISH,&Q);Q.Flags=Cut?4:2;Q.Body.Publish.Topic=XRT_STR_LITERAL("ws/topic");Q.Body.Publish.Payload=XRT_BYTES_LITERAL("x\0z");xfuture* Old=NULL;testRequire(xmqttClientPublishAsync(L.Client,&Q,10000,&Old)==XMQTT_ADMISSION_ACCEPTED,"ordinary leased publication at ACK cut");wrWait(Cut==2?&S.Base.Pubrels:&S.Base.Publishes,1,"actual old ACK barrier");xwsstream* Peer=xrtAtomicPtrLoad(&S.Base.Connections[0].Peer.Base.Server,XMEMORY_ACQUIRE);testRequire(xrtWsStreamAbort(Peer)&&xmqttClientWaitFor(L.Client,15000)==XWAIT_OK,"old native channel physically closed under its lease");const xmqttwriteresult* Result=mqttWsFuture(Old);testRequire(Result->Status!=XMQTT_STATUS_OK&&Result->Delivery==XMQTT_MAY_HAVE_REACHED_PEER,"old conservative delivery result");xrtSleep(20);testRequire(xrtAtomic32Load(&S.Base.Factories,XMEMORY_ACQUIRE)==1&&xmqttReconnectRelease(&L),"old lease prevents new factory");wrOnline(R,2,&L);testRequire(mrInfo(L.Client).Resumed&&mrInfo(L.Client).Established,"new actual native PSK handshake");wrWait(Cut==2?&S.Base.Pubrels:&S.Base.Replays,Cut==2?2:1,"canonical MQTT Session replay on resumed TLS");mcIssue(&S);(void)mrCaptured(L.Client,1);testRequire(xrtAtomic32Load(&S.Resumed,XMEMORY_ACQUIRE)&&xrtAtomic32Load(&S.TLS.Lookups,XMEMORY_ACQUIRE),"actual native peer confirms resumption");testRequire(xmqttReconnectRelease(&L),"return second generation lease");wrStop(&S.Base,R);testRequire(Result==xrtFutureValue(Old)&&Result->Status!=XMQTT_STATUS_OK,"old result remains immutable through all controller/native joins");xtlsresumeinfo Info;testRequire(xrtTlsResumeInfo(S.Credential,&Info)&&Info.Secret.Size,"caller credential survives all controller/Engine owners");xrtTlsResumeRelease(S.Credential);xrtTlsResumeRelease(S.TLS.ServerTicket);xrtFutureDestroy(Old);
}
int main(void){for(unsigned V=0;V<2;++V)for(unsigned R=0;R<2;++R)for(unsigned C=0;C<3;++C)mcCase(V?XMQTT_VERSION_311:XMQTT_VERSION_5,R?4:0,C);puts("[PASS] automatic WSS TLS PSK plus independent MQTT Session recovery and immutable old outcomes");return 0;}
